raw=root/'raw';raw.mkdir(exist_ok=True)
q=load(5);p=part(q,'q2');p.pop('clozeStem');p.pop('dropdowns');p['itemType']='multiple_choice';p['ngnSkill']='evaluate_outcomes';bi(p['stem'],'At the four-hour hospice follow-up, the client reports easier breathing and occasionally sleeps after prescribed morphine. Which nursing assessment is most appropriate before the next dose?','在四小时后的安宁疗护随访中，患者报告呼吸较轻松，按医嘱服用吗啡后偶尔入睡。下一剂给药前，最合适的护理评估是什么？');p['options']=[{'id':'A',**pair('Reassess breathlessness, respiratory rate and depth, and arousability; use the findings to evaluate benefit and possible opioid toxicity before following the prescribed dose plan.','重新评估呼吸困难、呼吸频率及深度和可唤醒程度；根据发现判断疗效及可能的阿片毒性，再执行医嘱剂量计划。')},{'id':'B',**pair('Interpret any sleep as proof of successful comfort care and give the next dose without a respiratory assessment.','将任何入睡都视为舒适护理成功的证据，无需评估呼吸即可给予下一剂。')},{'id':'C',**pair('Assess oxygen saturation alone because it fully measures opioid effect on ventilation.','只评估血氧饱和度，因为它能完全反映阿片对通气的影响。')},{'id':'D',**pair('Increase the morphine dose independently until the respiratory rate is as low as possible.','自行增加吗啡剂量，直到呼吸频率尽可能低。')}];p['correct']=['A'];p['rationale']={'correct':pair('Relief is assessed by the client’s comfort and breathing effort while checking arousability and ventilation. Occasional sleep alone neither establishes toxicity nor proves safety. Morphine can depress respiration; new excessive sedation or slow, shallow breathing requires prompt reassessment and escalation under the prescribed plan.','应根据患者舒适感及呼吸做功评价缓解效果，同时检查可唤醒程度和通气。偶尔入睡本身既不能确定毒性，也不能证明安全。吗啡可抑制呼吸；新出现的过度镇静或缓慢浅呼吸，需要按医嘱计划及时复评并升级处理。'),'byChoice':[{'refId':'A',**pair('Assess benefit and adverse effects together before the next prescribed dose.','下一次医嘱给药前需同时评估获益与不良反应。')},{'refId':'B',**pair('Sleep must be assessed in context, including ease of arousal and ventilation.','必须结合可唤醒程度及通气情况评价睡眠。')},{'refId':'C',**pair('Oxygen saturation does not replace assessment of respiratory depth, rate and arousability.','血氧饱和度不能替代呼吸深度、频率和可唤醒程度评估。')},{'refId':'D',**pair('Titrate only under the prescribed plan toward symptom relief with monitoring, not toward the lowest respiratory rate.','只可按医嘱计划在监测下滴定以缓解症状，目标不是使呼吸频率最低。')}]};bi(p['testTakingStrategy'],'Judge symptom relief alongside arousability and ventilation, then follow the prescribed plan.','同时判断症状缓解、可唤醒程度和通气，再遵循医嘱计划。');anchor(p,'stage_hospice_followup')
# Collateral rationale repairs prevent the preserved sibling from contradicting replacement safety teaching.
p1=part(q,'q1');bi(p1['rationale']['correct'],'For this comfort-focused hospice client, prescribed low-dose morphine may relieve distressing breathlessness. Reassess symptoms, sedation and breathing as doses are carefully titrated. Treatment of reversible contributors, including congestion, should be individualized to the goals of care; morphine is not a substitute for that assessment.','对这名以舒适为目标的安宁疗护患者，医嘱低剂量吗啡可缓解痛苦性呼吸困难。谨慎滴定剂量时须复评症状、镇静及呼吸。应根据照护目标个体化处理淤血等可逆因素；吗啡不能替代该评估。');bi(obj(p1['rationale']['byChoice'],'A','refId'),'Prescribed low-dose morphine can reduce the distress of breathlessness, with individualized titration and monitoring.','医嘱低剂量吗啡可减轻呼吸困难的痛苦，需个体化滴定及监测。');bi(q['rationale']['correct'],'This case considers prescribed symptom relief for hospice breathlessness, nonpharmacologic comfort measures, and assessment of benefit and adverse effects.','本病例考察安宁疗护呼吸困难的医嘱症状缓解、非药物舒适措施，以及获益和不良反应评估。');r=obj(part(q,'q4')['rationale']['byChoice'],'B','refId');bi(r,'Relaxation and restful sleep can accompany comfort, but arousability and breathing still require assessment.','放松与安静睡眠可伴随舒适改善，但仍需评估可唤醒程度及呼吸。')
(raw/'gemini-c17-palliative-replacement.json').write_text(json.dumps({'meta':{'schemaVersion':'2.1'},'questions':[q]},ensure_ascii=False,indent=2)+'\n')
q=load(13);p=part(q,'q3');p['itemType']='select_all';bi(p['stem'],'At Stage 2, the PICC culture has flagged positive before the simultaneously drawn peripheral culture. Which actions should the nurse coordinate while paired-culture confirmation is pending? Select all that apply.','在第 2 阶段，PICC 血培养早于同时抽取的外周血培养报阳。在等待配对培养确认时，护士应协调哪些措施？选择所有适用项。');p['options'].extend([{'id':'opt_E',**pair('Delay prescribed antimicrobial treatment until the organism and source are definitively confirmed.','推迟医嘱抗菌治疗，直到病原体和感染源被最终确认。')},{'id':'opt_F',**pair('Require a replacement central catheter to be inserted before any source-control removal can occur.','要求必须先置入替代中心静脉导管，才可实施任何感染源控制性拔管。')}]);p['correct']=['opt_A','opt_B','opt_C','opt_D'];bi(p['rationale']['correct'],'Report the concerning culture result, ensure prompt prescribed antimicrobial therapy, coordinate necessary access and glucose support, and implement source-control orders. These tasks require coordination rather than a fixed four-step sequence. A new central line is not a universal prerequisite for source control. Paired cultures growing the same organism with the catheter sample positive at least two hours earlier support CRBSI.','应报告令人担忧的培养结果，确保及时按医嘱抗菌治疗，协调必要通路及血糖支持，并执行感染源控制医嘱。这些任务需要协调，而非固定四步顺序。新中心静脉导管并非感染源控制的普遍前提。同一病原体的配对培养中，导管血样至少提前两小时报阳支持 CRBSI。');p['rationale']['byChoice']=[{'refId':'opt_A',**pair('Prompt communication supports reassessment of antimicrobial and source-control plans.','及时报告支持重新评估抗菌及感染源控制方案。')},{'refId':'opt_B',**pair('The prescribed empiric antimicrobial should not wait for final paired-culture confirmation.','医嘱经验性抗菌治疗不应等待最终配对培养确认。')},{'refId':'opt_C',**pair('Coordinate access, PN interruption management and glucose monitoring with the team while source control is arranged.','安排感染源控制的同时，与团队协调通路、PN 中断管理及血糖监测。')},{'refId':'opt_D',**pair('Carry out removal when ordered; coordinate ongoing treatment according to clinical urgency and the team’s plan.','按医嘱执行拔管；根据临床紧迫性及团队计划协调持续治疗。')},{'refId':'opt_E',**pair('Waiting for definitive microbiology may dangerously delay treatment.','等待最终微生物结果可能造成危险的治疗延误。')},{'refId':'opt_F',**pair('Alternative access planning is important, but the timing of removal and new access is an individualized source-control decision.','替代通路规划很重要，但拔管与新通路的时机属于个体化感染源控制决策。')}];bi(p['testTakingStrategy'],'Coordinate urgent treatment, source control and continued supportive care; distinguish actual prerequisites from tasks that may proceed together.','协调紧急治疗、感染源控制和持续支持照护；区分真正的前提条件和可以并行的任务。');anchor(p,'stage_2')
c=content(q,1);rep(c,'en',' and orders the interventional radiology team to be on standby for possible PICC removal and source-control planning','');rep(c,'zh','，并指示介入放射团队待命，以便计划可能的PICC拔除及感染源控制','');rep(c,'en','>2-hour differential time to positivity','a differential time to positivity of at least 2 hours');rep(c,'zh','报阳时间差大于2小时','报阳时间差至少2小时');c=content(q,2);rep(c,'en','more than 2 hours before','at least 2 hours before');rep(c,'zh','早超过2小时','早至少2小时')
